from marshmallow import Schema, fields


class PlainItemSchema(Schema):
    id = fields.Int(dump_only=True)  # The id field is defined as an integer field that is marked as dump_only. This means that when serializing an Item object to JSON, the id field will be included in the output, but when deserializing JSON data into an Item object, the id field will be ignored. This is useful for fields that are generated by the database and should not be provided by the client.
    name = fields.Str(required=True)  # The name field is defined as a string field that is required. This means that when deserializing JSON data into an Item object, the name field must be present and cannot be null or empty. If the name field is missing or invalid, a validation error will be raised.
    price = fields.Float(required=True)  # The price field is defined as a float field that is required. Similar to the name field, this means that when deserializing JSON data into an Item object, the price field must be present and cannot be null or empty. If the price field is missing or invalid, a validation error will be raised.
    # store_id = fields.Int(required=True)  # The store_id field is defined as an integer field that is required. This means that when deserializing JSON data into an Item object, the store_id field must be present and cannot be null or empty. If the store_id field is missing or invalid, a validation error will be raised. This field is used to associate the item with a specific store in the database.


class PlainStoreSchema(Schema):
    id = fields.Int(dump_only=True)  # The id field is defined as an integer field that is marked as dump_only. This means that when serializing a Store object to JSON, the id field will be included in the output, but when deserializing JSON data into a Store object, the id field will be ignored. This is useful for fields that are generated by the database and should not be provided by the client.
    name = fields.Str(required=True)  # The name field is defined as a string field that is required. This means that when deserializing JSON data into a Store object, the name field must be present and cannot be null or empty. If the name field is missing or invalid, a validation error will be raised.


class PlainTagSchema(Schema):
    id = fields.Int(dump_only=True)  # The id field is defined as an integer field that is marked as dump_only. This means that when serializing a Tag object to JSON, the id field will be included in the output, but when deserializing JSON data into a Tag object, the id field will be ignored. This is useful for fields that are generated by the database and should not be provided by the client.
    name = fields.Str()         # The name field is defined as a string field that is not required. This means that when deserializing JSON data into a Tag object, the name field can be present or absent. If the name field is present, it will be used to update the corresponding attribute of the Tag object. If it is absent, the existing value of the name attribute will remain unchanged.
    # name = fields.Str(required=True)  # The name field is defined as a string field that is required. This means that when deserializing JSON data into a Tag object, the name field must be present and cannot be null or empty. If the name field is missing or invalid, a validation error will be raised.
